-- Convert an installed native video table before enabling atomic final publication.\n-- Empty extension-only migration databases may not contain the MACCMS core table yet.\n-- Back up the database and schedule this potentially long table rebuild during maintenance.\nSET @maccms_vod_exists = (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '__PREFIX__vod');\nSET @maccms_vod_engine_sql = IF(@maccms_vod_exists = 1, 'ALTER TABLE `__PREFIX__vod` ENGINE=InnoDB', 'SELECT 1');\nPREPARE maccms_vod_engine_statement FROM @maccms_vod_engine_sql;\nEXECUTE maccms_vod_engine_statement;\nDEALLOCATE PREPARE maccms_vod_engine_statement;\n